// Agent 1 Level 1 - Agent 002 Collaboration
// Max lines: 50, Token budget: 2000

async function startLevel1() {
  // Initialize level 1 state
  if (!global.level1State) {
    global.level1State = { completed: false, agentsReady: false };
  }

  // Check if agent_002 is ready for collaboration
  const agent002Ready = await checkAgentStatus(2);
  const selfReady = await checkAgentStatus(1);

  // If agent_002 isn't ready, wait and retry
  while (!agent002Ready || !selfReady) {
    await wait(1000);
    const ready = await checkAgentStatus(2);
    const self = await checkAgentStatus(1);
    agent002Ready = ready;
    selfReady = self;
    if (ready && self) break;
  }

  // Start collecting resources for level 1
  await collectItem('wood', 5);
  await collectItem('metal', 5);

  // Open necessary doors for level 1
  await openDoor(1);
  await openDoor(2);

  // Coordinate with agent_002 on progress
  await shareProgress(2);
  await syncAgents();

  // Complete level 1 objective
  await completeObjective('level1');
  global.level1State.completed = true;
  await finishLevel(1);
}

async function checkAgentStatus(id) {
  // Ensure agent_002 is ready to collaborate
  const status = await getAgentStatus(id);
  if (!status.ready) {
    await waitUntilAgentReady(id);
  }
  return status.ready;
}

async function shareProgress(targetId) {
  // Share current level 1 progress with agent_002
  const levelProgress = getLevelProgress();
  await broadcastMessage('Level1', levelProgress, targetId);
}

async function syncAgents() {
  // Ensure both agents are in sync for level 1
  await awaitAgentSync();
}

